create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,phone text,is_admin boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),name text not null,description text,price numeric(12,2) not null check(price>=0),category text not null check(category in ('shirts','shorts','trousers','hoodies','shoes','accessories')),stock integer not null default 0 check(stock>=0),is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.product_images(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete cascade,image_url text,display_order integer not null default 0,is_primary boolean not null default false);
create table if not exists public.product_sizes(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete cascade,size text not null,stock_qty integer not null default 0 check(stock_qty>=0));
create table if not exists public.orders(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete restrict,customer_name text not null,customer_email text not null,customer_phone text not null,delivery_type text not null check(delivery_type in ('delivery','pickup')),delivery_address text,notes text,total_amount numeric(12,2) not null default 0,status text not null default 'pending' check(status in ('pending','paid','shipped','delivered','cancelled')),paystack_reference text unique,paystack_transaction_id text,created_at timestamptz not null default now());
create table if not exists public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,product_id uuid not null references public.products(id) on delete restrict,product_name text not null,size text not null,quantity integer not null check(quantity>0),unit_price numeric(12,2) not null check(unit_price>=0));
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select coalesce((select is_admin from public.profiles where id=auth.uid()),false);$$;
alter table public.profiles enable row level security;alter table public.products enable row level security;alter table public.product_images enable row level security;alter table public.product_sizes enable row level security;alter table public.orders enable row level security;alter table public.order_items enable row level security;
drop policy if exists "profiles own select" on public.profiles;drop policy if exists "profiles own update" on public.profiles;create policy "profiles own select" on public.profiles for select to authenticated using(auth.uid()=id or public.is_admin());create policy "profiles own update" on public.profiles for update to authenticated using(auth.uid()=id) with check(auth.uid()=id);
drop policy if exists "products public active select" on public.products;drop policy if exists "products admin insert" on public.products;drop policy if exists "products admin update" on public.products;drop policy if exists "products admin delete" on public.products;create policy "products public active select" on public.products for select to anon,authenticated using(is_active or public.is_admin());create policy "products admin insert" on public.products for insert to authenticated with check(public.is_admin());create policy "products admin update" on public.products for update to authenticated using(public.is_admin()) with check(public.is_admin());create policy "products admin delete" on public.products for delete to authenticated using(public.is_admin());
drop policy if exists "images public select" on public.product_images;drop policy if exists "images admin insert" on public.product_images;drop policy if exists "images admin update" on public.product_images;drop policy if exists "images admin delete" on public.product_images;create policy "images public select" on public.product_images for select to anon,authenticated using((select is_active from public.products where id=product_id) or public.is_admin());create policy "images admin insert" on public.product_images for insert to authenticated with check(public.is_admin());create policy "images admin update" on public.product_images for update to authenticated using(public.is_admin()) with check(public.is_admin());create policy "images admin delete" on public.product_images for delete to authenticated using(public.is_admin());
drop policy if exists "sizes public select" on public.product_sizes;drop policy if exists "sizes admin insert" on public.product_sizes;drop policy if exists "sizes admin update" on public.product_sizes;drop policy if exists "sizes admin delete" on public.product_sizes;create policy "sizes public select" on public.product_sizes for select to anon,authenticated using((select is_active from public.products where id=product_id) or public.is_admin());create policy "sizes admin insert" on public.product_sizes for insert to authenticated with check(public.is_admin());create policy "sizes admin update" on public.product_sizes for update to authenticated using(public.is_admin()) with check(public.is_admin());create policy "sizes admin delete" on public.product_sizes for delete to authenticated using(public.is_admin());
drop policy if exists "orders own select" on public.orders;drop policy if exists "orders own insert" on public.orders;drop policy if exists "orders admin update" on public.orders;create policy "orders own select" on public.orders for select to authenticated using(auth.uid()=user_id or public.is_admin());create policy "orders own insert" on public.orders for insert to authenticated with check(auth.uid()=user_id);create policy "orders admin update" on public.orders for update to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists "items own select" on public.order_items;drop policy if exists "items own insert" on public.order_items;create policy "items own select" on public.order_items for select to authenticated using((select user_id from public.orders where id=order_id)=auth.uid() or public.is_admin());create policy "items own insert" on public.order_items for insert to authenticated with check((select user_id from public.orders where id=order_id)=auth.uid() or public.is_admin());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,full_name,phone) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),coalesce(new.raw_user_meta_data->>'phone',''));return new;end;$$;drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.process_paid_order(p_user_id uuid,p_customer_name text,p_customer_email text,p_customer_phone text,p_delivery_type text,p_delivery_address text,p_notes text,p_total_amount numeric,p_reference text,p_transaction_id text,p_items jsonb) returns setof public.orders language plpgsql security definer set search_path=public as $$declare new_order public.orders;item jsonb;sz public.product_sizes;pr public.products;begin if exists(select 1 from public.orders where paystack_reference=p_reference) then return query select * from public.orders where paystack_reference=p_reference;return;end if;if p_delivery_type='delivery' and nullif(trim(coalesce(p_delivery_address,'')),'') is null then raise exception 'Delivery address is required';end if;insert into public.orders(user_id,customer_name,customer_email,customer_phone,delivery_type,delivery_address,notes,total_amount,status,paystack_reference,paystack_transaction_id) values(p_user_id,p_customer_name,p_customer_email,p_customer_phone,p_delivery_type,p_delivery_address,p_notes,p_total_amount,'paid',p_reference,p_transaction_id) returning * into new_order;for item in select * from jsonb_array_elements(p_items) loop select * into pr from public.products where id=(item->>'product_id')::uuid for update;if not found or not pr.is_active then raise exception 'Product is unavailable';end if;if (item->>'size') is not null and (item->>'size')<>'One Size' then select * into sz from public.product_sizes where product_id=pr.id and size=item->>'size' for update;if not found or sz.stock_qty<(item->>'quantity')::int then raise exception 'Insufficient size stock';end if;update public.product_sizes set stock_qty=stock_qty-(item->>'quantity')::int where id=sz.id;end if;if pr.stock<(item->>'quantity')::int then raise exception 'Insufficient stock';end if;update public.products set stock=stock-(item->>'quantity')::int,updated_at=now() where id=pr.id;insert into public.order_items(order_id,product_id,product_name,size,quantity,unit_price) values(new_order.id,pr.id,pr.name,item->>'size',(item->>'quantity')::int,pr.price);end loop;return next new_order;end;$$;grant execute on function public.process_paid_order(uuid,text,text,text,text,text,text,numeric,text,text,jsonb) to service_role;
insert into storage.buckets(id,name,public) values('product-images','product-images',true) on conflict(id) do update set public=true;drop policy if exists "public product images read" on storage.objects;drop policy if exists "admins upload product images" on storage.objects;drop policy if exists "admins update product images" on storage.objects;drop policy if exists "admins delete product images" on storage.objects;create policy "public product images read" on storage.objects for select using(bucket_id='product-images');create policy "admins upload product images" on storage.objects for insert to authenticated with check(bucket_id='product-images' and public.is_admin());create policy "admins update product images" on storage.objects for update to authenticated using(bucket_id='product-images' and public.is_admin()) with check(bucket_id='product-images' and public.is_admin());create policy "admins delete product images" on storage.objects for delete to authenticated using(bucket_id='product-images' and public.is_admin());
